# Surah An-Nisa (chapter 4) — part 14: ayat 131-140 (IDs 624-633)
SURAH = 4

ENTRIES = {
624: (
"اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور بے شک ہم نے ان لوگوں کو بھی حکم دیا جو تم سے پہلے کتاب دیے گئے اور تمہیں بھی کہ اللہ سے ڈرو — اور اگر تم کفر کرو تو بے شک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ بے پرواہ، تعریف کے لائق ہے",
"""۱۔ تقویٰ — ہر امت کے لیے مشترکہ حکم۔
۲۔ ’’وَلِلّٰہِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ‘‘ — اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — یعنی کائنات کی ہر چیز اللہ کی ملکیت ہے۔
۳۔ ’’وَلَقَدْ وَصَّيْنَا الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ اتَّقُوا اللّٰہَ‘‘ — اور بے شک ہم نے ان لوگوں کو بھی حکم دیا جو تم سے پہلے کتاب دیے گئے اور تمہیں بھی کہ اللہ سے ڈرو — یعنی تقویٰ کا حکم سب امتوں کو یکساں ملا ہے۔
۴۔ ’’وَإِن تَكْفُرُوا فَإِنَّ لِلّٰہِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللّٰہُ غَنِيًّا حَمِيدًا‘‘ — اور اگر تم کفر کرو تو بے شک اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ بے پرواہ، تعریف کے لائق ہے — یعنی اللہ کسی کی پرواہ نہیں کرتا۔
۵۔ عملی سبق: تقویٰ اختیار کرو؛ اللہ کی حدود میں رہو — وہ بے پرواہ ہے مگر مہربان۔"""
),
625: (
"اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ کارساز ہونے کو کافی ہے",
"""۱۔ کائنات سب اللہ کی ہے — اور وہی کافی کارساز ہے۔
۲۔ ’’وَلِلّٰہِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَىٰ بِاللّٰہِ وَكِيلًا‘‘ — اور اللہ ہی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ کارساز ہونے کو کافی ہے۔
۳۔ عملی سبق: ہر کام میں اللہ کو کافی سمجھو؛ اس پر بھروسہ رکھو۔"""
),
626: (
"اگر وہ چاہے تو تمہیں (لوگو) ہٹا دے اور دوسرے (لوگ) لائے — اور اللہ اس پر قادر ہے",
"""۱۔ اللہ کی قدرت — کسی کو بھی ہٹا کر دوسرے لا سکتا ہے۔
۲۔ ’’إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا النَّاسُ وَيَأْتِ بِآخَرِينَ وَكَانَ اللّٰہُ عَلَىٰ ذَٰلِكَ قَدِيرًا‘‘ — اگر وہ چاہے تو تمہیں (لوگو) ہٹا دے اور دوسرے (لوگ) لائے — اور اللہ اس پر قادر ہے — یعنی انسان کا وجود اللہ کی مشیت پر منحصر ہے۔
۳۔ عملی سبق: اللہ کی نعمت کی قدر کرو؛ تکبر نہ کرو — اللہ جب چاہے کسی کو اٹھا سکتا ہے۔"""
),
627: (
"جو کوئی دنیا کا ثواب چاہتا ہے — تو اللہ کے پاس دنیا کا بھی ثواب ہے اور آخرت کا بھی — اور اللہ سننے والا، دیکھنے والا ہے",
"""۱۔ اللہ کے پاس دنیا اور آخرت دونوں کا بدلہ ہے۔
۲۔ ’’مَّن كَانَ يُرِيدُ ثَوَابَ الدُّنْيَا فَعِندَ اللّٰہِ ثَوَابُ الدُّنْيَا وَالْآخِرَۃِ‘‘ — جو کوئی دنیا کا ثواب چاہتا ہے — تو اللہ کے پاس دنیا کا بھی ثواب ہے اور آخرت کا بھی — یعنی اللہ دونوں جہانوں کا مالک ہے۔
۳۔ ’’وَكَانَ اللّٰہُ سَمِيعًا بَصِيرًا‘‘ — اور اللہ سننے والا، دیکھنے والا ہے۔
۴۔ عملی سبق: صرف دنیا نہ مانگو؛ آخرت کی طلب رکھو — اللہ دونوں دے سکتا ہے۔"""
),
628: (
"اے ایمان والو! انصاف پر ڈٹے رہو — اللہ کے لیے گواہ بنو — اگرچہ (فیصلہ) تمہارے اپنے یا تمہارے والدین اور قرابت داروں کے خلاف ہو — چاہے وہ غنی ہو یا فقیر — اللہ ان دونوں کا زیادہ خیر خواہ ہے — پس تم خواہشِ نفس کی پیروی نہ کرو کہ انصاف سے ہٹ جاؤ — اور اگر تم لپیٹو یا اعراض کرو — تو بے شک اللہ تمہارے اعمال سے باخبر ہے",
"""۱۔ انصاف — ہر حال میں، ہر شخص کے خلاف بھی۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلّٰہِ وَلَوْ عَلَىٰ أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ‘‘ — اے ایمان والو! انصاف پر ڈٹے رہو — اللہ کے لیے گواہ بنو — اگرچہ (فیصلہ) تمہارے اپنے یا تمہارے والدین اور قرابت داروں کے خلاف ہو — یعنی حق کی گواہی سب سے بڑھ کر ہے۔
۳۔ ’’إِن يَكُن غَنِيًّا أَوْ فَقِيرًا فَاللّٰہُ أَوْلَىٰ بِهِمَا‘‘ — چاہے وہ غنی ہو یا فقیر — اللہ ان دونوں کا زیادہ خیر خواہ ہے — یعنی مالدار یا غریب دونوں کے ساتھ عدل کرو۔
۴۔ ’’فَلَا تَتَّبِعُوا الْهَوَىٰ أَن تَعْدِلُوا‘‘ — پس تم خواہشِ نفس کی پیروی نہ کرو کہ انصاف سے ہٹ جاؤ — یعنی ذاتی مفاد انصاف کو نہ دبائے۔
۵۔ ’’وَإِن تَلْوُوا أَوْ تُعْرِضُوا فَإِنَّ اللّٰہَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا‘‘ — اور اگر تم لپیٹو یا اعراض کرو — تو بے شک اللہ تمہارے اعمال سے باخبر ہے — یعنی جھوٹ اور اعراض اللہ کے علم میں ہے۔
۶۔ عملی سبق: انصاف کرو خواہ تم خود یا اپنے عزیز اس کے بہ زور ہوں؛ گواہی کبھی نہ چھپاؤ۔"""
),
629: (
"اے ایمان والو! اللہ پر، اس کے رسول پر اور اس کتاب پر جو اس نے اپنے رسول پر نازل فرمائی اور اس کتاب پر جو اس نے پہلے نازل کی ایمان لاؤ — اور جو کوئی اللہ، اس کے فرشتوں، اس کی کتابوں، اس کے رسولوں اور قیامت کے دن پر کفر کرے — اس نے بہت دور گمراہی میں بھٹک کر گم ہو گیا",
"""۱۔ مکمل ایمان — چھ ارکان پر پورا یقین۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا آمِنُوا بِاللّٰہِ وَرَسُولِهِ وَالْكِتَابِ الَّذِي نَزَّلَ عَلَىٰ رَسُولِهِ‘‘ — اے ایمان والو! اللہ پر، اس کے رسول پر اور اس کتاب پر جو اس نے اپنے رسول پر نازل فرمائی ایمان لاؤ — یعنی قرآن پر کامل ایمان ضروری ہے۔
۳۔ ’’وَالْكِتَابِ الَّذِي أَنزَلَ مِن قَبْلُ‘‘ — اور اس کتاب پر جو اس نے پہلے نازل کی — یعنی سابقہ الہامی کتابوں پر بھی ایمان لاؤ۔
۴۔ ’’وَمَن يَكْفُرْ بِاللّٰہِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا‘‘ — اور جو کوئی اللہ، اس کے فرشتوں، اس کی کتابوں، اس کے رسولوں اور قیامت کے دن پر کفر کرے — اس نے بہت دور گمراہی میں بھٹک کر گم ہو گیا۔
۵۔ عملی سبق: تمام ارکانِ ایمان پر پورا یقین رکھو؛ کسی ایک کا انکار گمراہی ہے۔"""
),
630: (
"بے شک جو لوگ ایمان لائے پھر کفر کیا پھر ایمان لائے پھر کفر کیا — پھر کفر میں بڑھتے چلے گئے — اللہ انہیں نہ بخشے گا اور نہ انہیں سیدھے راستے کی ہدایت دے گا",
"""۱۔ ایمان و کفر میں مسلسل ہیر پھیر — ہدایت کی راہ مسدود۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ ازْدَادُوا كُفْرًا‘‘ — بے شک جو لوگ ایمان لائے پھر کفر کیا پھر ایمان لائے پھر کفر کیا — پھر کفر میں بڑھتے چلے گئے — یعنی مسلسل بے یقینی اور ارتداد۔
۳۔ ’’لَّمْ يَكُنِ اللّٰہُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًا‘‘ — اللہ انہیں نہ بخشے گا اور نہ انہیں سیدھے راستے کی ہدایت دے گا — یعنی جو ہدایت کو مسلسل رد کرتے رہیں انہیں ہدایت نہیں ملتی۔
۴۔ عملی سبق: ایمان میں ثابت قدم رہو؛ بار بار ترک اور رجوع نہ کرو — یہ ایمان کو تباہ کرتا ہے۔"""
),
631: (
"آپ منافقین کو خوشخبری سنا دیں کہ ان کے لیے دردناک عذاب ہے",
"""۱۔ منافقین کے لیے بشارتِ عذاب۔
۲۔ ’’بَشِّرِ الْمُنَافِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا‘‘ — آپ منافقین کو خوشخبری سنا دیں کہ ان کے لیے دردناک عذاب ہے — یعنی منافقین کو سخت سزا ملے گی۔
۳۔ عملی سبق: منافقانہ رویہ اختیار نہ کرو؛ خلوصِ نیت سے ایمان رکھو۔"""
),
632: (
"یہی وہ لوگ ہیں جو کافروں کو — مؤمنین کے بجائے — دوست بناتے ہیں — کیا وہ ان کے پاس عزت ڈھونڈتے ہیں؟ — بے شک تمام عزت اللہ ہی کے لیے ہے",
"""۱۔ کافروں سے دوستی کر کے عزت ڈھونڈنا — غلط حساب۔
۲۔ ’’الَّذِينَ يَتَّخِذُونَ الْكَافِرِينَ أَوْلِيَاءَ مِن دُونِ الْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ الْعِزَّۃَ‘‘ — یہی وہ لوگ ہیں جو کافروں کو — مؤمنین کے بجائے — دوست بناتے ہیں — کیا وہ ان کے پاس عزت ڈھونڈتے ہیں؟ — یعنی ان کا خیال ہے کہ کافروں سے عزت ملے گی۔
۳۔ ’’فَإِنَّ الْعِزَّۃَ لِلّٰہِ جَمِيعًا‘‘ — بے شک تمام عزت اللہ ہی کے لیے ہے — یعنی اصل عزت صرف اللہ کے پاس ہے۔
۴۔ عملی سبق: عزت صرف اللہ سے مانگو؛ کافروں کی دوستی سے عزت نہیں ملتی۔"""
),
633: (
"اور بے شک کتاب میں تم سے بیان ہوا (حکم): جب تم سنو کہ اللہ کی آیات کا انکار کیا جا رہا ہے اور ان سے مذاق کیا جا رہا ہے — تو ان کے ساتھ مت بیٹھو جب تک وہ کسی اور بات میں مشغول نہ ہو جائیں — ورنہ (اگر بیٹھو تو) تم بھی انہیں جیسے ہو جاؤ گے — بے شک اللہ منافقین اور کافروں کو — سب — جہنم میں جمع کرنے والا ہے",
"""۱۔ آیاتِ الٰہی کا مذاق اڑانے والوں کے ساتھ نہ بیٹھو۔
۲۔ ’’وَقَدْ نَزَّلَ عَلَيْكُمْ فِي الْكِتَابِ أَنْ إِذَا سَمِعْتُمْ آيَاتِ اللّٰہِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا مَعَهُمْ حَتَّىٰ يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ‘‘ — اور بے شک کتاب میں تم سے بیان ہوا (حکم): جب تم سنو کہ اللہ کی آیات کا انکار کیا جا رہا ہے اور ان سے مذاق کیا جا رہا ہے — تو ان کے ساتھ مت بیٹھو جب تک وہ کسی اور بات میں مشغول نہ ہو جائیں — یعنی ایسی محفلوں میں بیٹھنا حرام ہے۔
۳۔ ’’إِنَّكُمْ إِذًا مِّثْلُهُمْ‘‘ — ورنہ (اگر بیٹھو تو) تم بھی انہیں جیسے ہو جاؤ گے — یعنی خاموشی سے بیٹھنا بھی گناہ میں شریک ہونے کے مترادف ہے۔
۴۔ ’’إِنَّ اللّٰہَ جَامِعُ الْمُنَافِقِينَ وَالْكَافِرِينَ فِي جَهَنَّمَ جَمِيعًا‘‘ — بے شک اللہ منافقین اور کافروں کو — سب — جہنم میں جمع کرنے والا ہے۔
۵۔ عملی سبق: اللہ کی آیات کا مذاق اڑانے والوں سے فوری فاصلہ رکھو؛ وہ محفل چھوڑ دو۔"""
),
}
